sys_script.script:
(function executeRule(current, previous) {
  if (!current.scholarship_name || current.scholarship_name.nil()) {
    gs.addErrorMessage('Scholarship Program Name is required.');
    current.setAbortAction(true);
    return;
  }
  var amount = parseFloat(current.scholarship_amount);
  if (isNaN(amount) || amount <= 0) {
    gs.addErrorMessage('Scholarship Amount must be greater than zero.');
    current.setAbortAction(true);
    return;
  }
  var seats = parseInt(current.available_seats, 10);
  if (isNaN(seats) || seats < 0) {
    gs.addErrorMessage('Available Seats cannot be negative.');
    current.setAbortAction(true);
    return;
  }
  var minPerc = parseFloat(current.minimum_percentage);
  if (!isNaN(minPerc) && (minPerc < 0 || minPerc > 100)) {
    gs.addErrorMessage('Minimum Eligibility Percentage must be between 0 and 100.');
    current.setAbortAction(true);
    return;
  }
  var maxInc = parseFloat(current.maximum_family_income);
  if (!isNaN(maxInc) && maxInc < 0) {
    gs.addErrorMessage('Maximum Family Income cannot be negative.');
    current.setAbortAction(true);
    return;
  }
  // If deadline has passed, mark as expired
  if (current.end_date && !current.end_date.nil()) {
    var endDt = new GlideDateTime(current.end_date.getDisplayValue());
    var nowDt = new GlideDateTime();
    if (endDt.getNumericValue() < nowDt.getNumericValue()) {
      current.program_status = 'expired';
    }
  }
})(current, previous);
